def server_case_weights(case):
    """Return the exact base weights defined by the case catalog.

    The live server intentionally uses the same ``chance`` values that are
    exposed by CASES_BY_ID. There is no additional hidden rarity multiplier
    or historical-weight table here, so the catalog and server use identical
    base odds. Player-specific luck/bad-luck adjustments are applied before
    this function is called.
    """
    items = list(case.get('items') or [])
    return [max(0.0, float(item.get('chance', 0))) for item in items]

def weighted_pick(case):
    items = list(case.get('items') or [])
    if not items:
        raise ValueError('В кейсе нет предметов')
    weights = server_case_weights(case)
    total = sum(weights)
    if total <= 0:
        return items[0]
    import secrets
    roll = secrets.randbelow(10000000) / 10000000 * total
    acc = 0.0
    for item, weight in zip(items, weights):
        acc += max(0.0, float(weight))
        if roll < acc:
            return item
    return items[-1]
